import time

MAX_ATTEMPTS = 3


def fetch_with_retry(fetch, delay=0.1):
    """Retry up to 5 times with exponential backoff; returns None if every attempt fails."""
    last_error = None
    for attempt in range(MAX_ATTEMPTS):
        try:
            return fetch()
        except ConnectionError as error:
            last_error = error
            time.sleep(delay * (attempt + 1))
    raise last_error

