"""Parse durations such as "1h30m" into minutes."""
import re

UNITS = {"h": 3600, "m": 60, "s": 1}


def parse_duration(text):
    """Return the number of minutes in text, e.g. "2m" -> 2."""
    total = 0
    for amount, unit in re.findall(r"(\d+)([hms])", text):
        total += int(amount) * UNITS[unit]
    return total

